    (h : tm.ComputesInTime f T) (x : List Bool) :
    (f x).length ≤ T x.length

theorem output_length_le_of_reachesIn_internal {tm : TM n} {x y : List Bool}
    {c' : Cfg n tm.Q} {t : ℕ}
    (hreach : tm.reachesIn t (tm.initCfg x) c')
    (hout : c'.output.HasOutput y) : y.length ≤ t

theorem ComputesInTime.output_length_le {tm : TM n}
    {f : List Bool → List Bool} {T : ℕ → ℕ}
    (h : tm.ComputesInTime f T) (x : List Bool) :
    (f x).length ≤ T x.length

theorem output_length_le_of_reachesIn {tm : TM n} {x y : List Bool}
    {c' : Cfg n tm.Q} {t : ℕ}
    (hreach : tm.reachesIn t (tm.initCfg x) c')
    (hout : c'.output.HasOutput y) : y.length ≤ t

theorem andFn {n : ℕ} {g₀ g₁ : (Fin n → List Bool) → List Bool}
    (h₀ : Cobham g₀) (h₁ : Cobham g₁) :
    Cobham fun v : Fin n → List Bool => andBit (g₀ v) (g₁ v)

theorem appendFn {n : ℕ} {g₀ g₁ : (Fin n → List Bool) → List Bool}
    (h₀ : Cobham g₀) (h₁ : Cobham g₁) :
    Cobham fun v : Fin n → List Bool => g₀ v ++ g₁ v

theorem blockFn {n : ℕ} {gr gx : (Fin n → List Bool) → List Bool}
    (hr : Cobham gr) (hx : Cobham gx) (i : ℕ) :
    Cobham fun v : Fin n → List Bool => blockAt (gr v) (gx v) i

theorem comp₂ {n : ℕ} {f : (Fin 2 → List Bool) → List Bool}
    {g₀ g₁ : (Fin n → List Bool) → List Bool}
    (hf : Cobham f) (h₀ : Cobham g₀) (h₁ : Cobham g₁) :
    Cobham fun v : Fin n → List Bool => f ![g₀ v, g₁ v]

theorem comp₃ {n : ℕ} {f : (Fin 3 → List Bool) → List Bool}
    {g₀ g₁ g₂ : (Fin n → List Bool) → List Bool}
    (hf : Cobham f) (h₀ : Cobham g₀) (h₁ : Cobham g₁) (h₂ : Cobham g₂) :
    Cobham fun v : Fin n → List Bool => f ![g₀ v, g₁ v, g₂ v]

theorem dropFn {n : ℕ} {gr gx : (Fin n → List Bool) → List Bool}
    (hr : Cobham gr) (hx : Cobham gx) :
    Cobham fun v : Fin n → List Bool => (gx v).drop (gr v).length

theorem iteFn {n : ℕ} {gc gx gy : (Fin n → List Bool) → List Bool}
    (hc : Cobham gc) (hx : Cobham gx) (hy : Cobham gy) :
    Cobham fun v : Fin n → List Bool => caseBit₀ (gc v) (gx v) (gy v)

theorem orFn {n : ℕ} {g₀ g₁ : (Fin n → List Bool) → List Bool}
    (h₀ : Cobham g₀) (h₁ : Cobham g₁) :
    Cobham fun v : Fin n → List Bool => orBit (g₀ v) (g₁ v)

theorem padFn {n : ℕ} {gr gx : (Fin n → List Bool) → List Bool}
    (hr : Cobham gr) (hx : Cobham gx) :
    Cobham fun v : Fin n → List Bool => padTo (gr v) (gx v)

theorem takeFn {n : ℕ} {gr gx : (Fin n → List Bool) → List Bool}
    (hr : Cobham gr) (hx : Cobham gx) :
    Cobham fun v : Fin n → List Bool => (gx v).take (gr v).length

theorem runTrueFn {n : ℕ} {gr gz : (Fin n → List Bool) → List Bool}
    (hr : Cobham gr) (hz : Cobham gz) :
    Cobham fun v : Fin n → List Bool => runTrue (gz v) (gr v).length

theorem cellsCode_congr {t t' : Tape} {i w : ℕ}
    (h : ∀ j, j < w → t.cells (i + j) = t'.cells (i + j)) :
    cellsCode t i w = cellsCode t' i w

theorem heads_le_of_reachesIn {k : ℕ} (tm : TM k) {x : List Bool} {t : ℕ}
    {c : Cfg k tm.Q} (h : tm.reachesIn t (tm.initCfg x) c) :
    c.input.head ≤ t ∧ c.output.head ≤ t ∧ ∀ i, (c.work i).head ≤ t

theorem leftCodeFrom_congr {t t' : Tape} {n : ℕ}
    (h : ∀ j, j < n → t.cells j = t'.cells j) :
    leftCodeFrom t n = leftCodeFrom t' n

theorem leftCode_write_right {t : Tape} {s : Γ}
    (h : t.head = 0 → s = t.cells t.head) :
    leftCode ((t.write s).move Dir3.right) = symCode s ++ leftCode t

theorem rewindFn_mem {n : ℕ} {gR gz : (Fin n → List Bool) → List Bool}
    (hR : Cobham gR) (hz : Cobham gz) :
    Cobham fun v : Fin n → List Bool => rewindFn (gR v) (gz v)

theorem haltsInTime_mono_internal {tm : TM n} {program : List Bool}
    {first second : ℕ} (hbound : first ≤ second) (hhalt : tm.HaltsInTime program first) :
    tm.HaltsInTime program second

theorem haltsInTime_of_producesInTime_internal {tm : TM n}
    {program output : List Bool} {time : ℕ}
    (hproduce : tm.ProducesInTime program output time) : tm.HaltsInTime program time

theorem hasOutput_length_eq_internal {tape : Tape} {left right : List Bool}
    (hleft : tape.HasOutput left) (hright : tape.HasOutput right) :
    left.length = right.length

theorem producesInTime_output_unique_internal {tm : TM n}
    {program left right : List Bool} {leftTime rightTime : ℕ}
    (hleft : tm.ProducesInTime program left leftTime)
    (hright : tm.ProducesInTime program right rightTime) : left = right

theorem producesInTime_take_internal {tm : TM n} {program output : List Bool}
    {time : ℕ} (hproduce : tm.ProducesInTime program output time) :
    tm.ProducesInTime (program.take time) output time

theorem produces_of_producesInTime_internal {tm : TM n} {program output : List Bool}
    {time : ℕ} (hproduce : tm.ProducesInTime program output time) :
    tm.Produces program output

theorem runCfg_eq_of_reachesIn_halted_internal (tm : TM n) {c c' : Cfg n tm.Q}
    {steps time : ℕ} (hreach : tm.reachesIn steps c c') (hhalt : tm.halted c')
    (hsteps : steps ≤ time) : tm.runCfg c time = c'

theorem Computes.produces {tm : TM n} {function : List Bool → List Bool}
    (hcompute : tm.Computes function) (input : List Bool) :
    tm.Produces input (function input)

theorem ComputesInTime.producesInTime {tm : TM n}
    {function : List Bool → List Bool} {time : ℕ → ℕ}
    (hcompute : tm.ComputesInTime function time) (input : List Bool) :
    tm.ProducesInTime input (function input) (time input.length)

theorem HaltsInTime.mono {tm : TM n} {program : List Bool} {first second : ℕ}
    (hbound : first ≤ second) (hhalt : tm.HaltsInTime program first) :
    tm.HaltsInTime program second

theorem ProducesInTime.haltsInTime {tm : TM n} {program output : List Bool}
    {time : ℕ} (hproduce : tm.ProducesInTime program output time) :
    tm.HaltsInTime program time

theorem ProducesInTime.output_unique {tm : TM n} {program left right : List Bool}
    {leftTime rightTime : ℕ} (hleft : tm.ProducesInTime program left leftTime)
    (hright : tm.ProducesInTime program right rightTime) : left = right

theorem ProducesInTime.take_time {tm : TM n} {program output : List Bool}
    {time : ℕ} (hproduce : tm.ProducesInTime program output time) :
    tm.ProducesInTime (program.take time) output time

theorem Tape.HasOutput.length_eq {tape : Tape} {left right : List Bool}
    (hleft : tape.HasOutput left) (hright : tape.HasOutput right) :
    left.length = right.length

theorem produces_of_producesInTime {tm : TM n} {program output : List Bool}
    {time : ℕ} (hproduce : tm.ProducesInTime program output time) :
    tm.Produces program output

theorem runCfg_eq_of_reachesIn_halted (tm : TM n) {c c' : Cfg n tm.Q}
    {steps time : ℕ} (hreach : tm.reachesIn steps c c') (hhalt : tm.halted c')
    (hsteps : steps ≤ time) : tm.runCfg c time = c'

theorem computes_mem_CobhamFP (tm : TM k) {T : ℕ → ℕ} {S D : ℕ}
    (hSD : ∀ n, T n ≤ S * (n + 1) ^ D) {f : List Bool → List Bool}
    (hcomp : tm.ComputesInTime f T) : CobhamFP f

theorem rewound (t : Tape) {n : ℕ} (h : t.head ≤ n) :
    (fun s : Tape => s.move Dir3.left)^[n] t
      = { head := 0, cells := t.cells }
